import { memo, useCallback, useMemo, useState } from 'react'

const Controls = memo(function Controls({ onAdd }: { onAdd: () => void }) {
  return <button onClick={onAdd}>+1</button>
})

export function Counter() {
  const [count, setCount] = useState(0)
  const [log, setLog] = useState<{ id: number; at: number }[]>([])
  const doubled = useMemo(() => count * 2, [count])
  const add = useCallback(() => {
    setCount((c) => c + 1)
    setLog((l) => [...l, { id: l.length, at: Date.now() }])
  }, [])

  return (
    <div>
      <Controls onAdd={add} />
      <p>{count} × 2 = {doubled}</p>
      {count > 9 && <p>Double digits.</p>}
      <ul>
        {log.map((e) => (
          <li key={e.id}>{new Date(e.at).toLocaleTimeString()}</li>
        ))}
      </ul>
    </div>
  )
}

