import { signal, computed } from '@pyreon/reactivity'
import { For, Show } from '@pyreon/core'

function Controls(props: { onAdd: () => void }) {
  return <button onClick={props.onAdd}>+1</button>
}

export function Counter() {
  const count = signal(0)
  const log = signal<{ id: number; at: number }[]>([])
  const doubled = computed(() => count() * 2)
  const add = () => {
    count.update((c) => c + 1)
    log.update((l) => [...l, { id: l.length, at: Date.now() }])
  }

  return (
    <div>
      <Controls onAdd={add} />
      <p>{count()} × 2 = {doubled()}</p>
      <Show when={() => count() > 9}>
        <p>Double digits.</p>
      </Show>
      <ul>
        <For each={log} by={(e) => e.id}>
          {(e) => <li>{new Date(e.at).toLocaleTimeString()}</li>}
        </For>
      </ul>
    </div>
  )
}

