'use plain'
import { state, derived } from '@pyreon/core/plain'

let count = state(0)
const double = derived(count * 2)

export function Counter({ label, step = 1 }: { label: string; step?: number }) {
  return <button onClick={() => { count += step }}>{label}: {count} / {double}</button>
}
